-- Скрипт для отката (удаления) тестовых данных
-- Важно: удалять в обратном порядке из-за foreign key constraints

-- 1. Удаляем связи работников с компаниями
DELETE FROM employees_companies
WHERE id IN (
             '20000000-0000-0000-0000-000000000001',
             '20000000-0000-0000-0000-000000000002',
             '20000000-0000-0000-0000-000000000003',
             '20000000-0000-0000-0000-000000000004',
             '20000000-0000-0000-0000-000000000005',
             '20000000-0000-0000-0000-000000000006',
             '20000000-0000-0000-0000-000000000007',
             '20000000-0000-0000-0000-000000000008',
             '20000000-0000-0000-0000-000000000009',
             '20000000-0000-0000-0000-000000000010'
    );

-- 2. Удаляем работников
DELETE FROM employees
WHERE id IN (
             '10000000-0000-0000-0000-000000000001',
             '10000000-0000-0000-0000-000000000002',
             '10000000-0000-0000-0000-000000000003',
             '10000000-0000-0000-0000-000000000004',
             '10000000-0000-0000-0000-000000000005',
             '10000000-0000-0000-0000-000000000006',
             '10000000-0000-0000-0000-000000000007',
             '10000000-0000-0000-0000-000000000008',
             '10000000-0000-0000-0000-000000000009',
             '10000000-0000-0000-0000-000000000010',
             '10000000-0000-0000-0000-000000000011'
    );

-- 3. Удаляем рестораны (компании)
DELETE FROM companies
WHERE id IN (
             '11111111-1111-1111-1111-111111111111',
             '22222222-2222-2222-2222-222222222222',
             '33333333-3333-3333-3333-333333333333'
    );